using DSAExperimentation.DataStructures.Trie;
namespace DSAExperimentation.Tests.LeetCodeCoverage.DesignAddAndSearchWordsDataStructure;
public sealed partial class DesignAddAndSearchWordsDataStructureTests { [Fact] public void WordDictionary_Example_SupportsDotWildcard(){var d=new WordDictionary();d.AddWord("bad");d.AddWord("dad");d.AddWord("mad");Assert.False(d.Search("pad"));Assert.True(d.Search("bad"));Assert.True(d.Search(".ad"));Assert.True(d.Search("b.."));} private sealed class WordDictionary{private readonly Trie<bool> _words=new();private readonly List<string> _all=[];public void AddWord(string word){_words.Set(word,true);_all.Add(word);}public bool Search(string pattern){if(!pattern.Contains('.'))return _words.HasKey(pattern);return _all.Any(w=>w.Length==pattern.Length&&w.Where((c,i)=>pattern[i]=='.'||pattern[i]==c).Count()==w.Length);}} }
